use std::rc::{Rc, Weak};

fn main() {
    let mut cache: HashMap<String, Weak<String>> = HashMap::new();
    let a = Rc::new(String::from("rust"));
    cache.insert(String::from("rust"), Rc::downgrade(&a));
    let hit = cache.get("rust").and_then(|w| w.upgrade());
    println!("{}", hit.is_some());
    drop(hit);
    drop(a);
    let hit = cache.get("rust").and_then(|w| w.upgrade());
    println!("{}", hit.is_some());
}

